// Test script for the POST /check endpoint
const request = require('supertest');
const app = require('./app.js');

describe('POST /check', () => {
  it('should evaluate simple rule expressions', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    console.log('Test 1 - Simple numeric comparison:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected result: true\n');
  });

  it('should evaluate string comparison rules', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.status === "approved"',
        context: { status: 'approved' }
      });

    console.log('Test 2 - String comparison:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected result: true\n');
  });

  it('should handle complex expressions', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.age >= 18 && ctx.country === "US"',
        context: { age: 21, country: 'US' }
      });

    console.log('Test 3 - Complex logical expression:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected result: true\n');
  });

  it('should access request properties', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'req.method === "POST"',
        context: {}
      });

    console.log('Test 4 - Accessing request properties:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected result: true\n');
  });

  it('should return false for failing rules', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.value < 0',
        context: { value: 10 }
      });

    console.log('Test 5 - False result:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected result: false\n');
  });

  it('should handle errors for invalid expressions', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.missing.property > 0', // Will throw ReferenceError
        context: { amount: 100 }
      });

    console.log('Test 6 - Invalid expression (error handling):');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected: 400 status with error message\n');
  });

  it('should validate missing rule field', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        context: { amount: 100 }
        // Missing 'rule' field
      });

    console.log('Test 7 - Missing rule field:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected: 400 status with validation error\n');
  });

  it('should validate missing context field', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100'
        // Missing 'context' field
      });

    console.log('Test 8 - Missing context field:');
    console.log('Response status:', response.status);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    console.log('Expected: 400 status with validation error\n');
  });
});

// Run tests
(async () => {
  const server = app.listen(3001, () => {
    console.log('Test server running on port 3001\n');
  });

  try {
    // Run all test cases
    const tests = [
      {
        name: 'Simple numeric comparison',
        request: { rule: 'ctx.amount > 100', context: { amount: 150 } }
      },
      {
        name: 'String comparison',
        request: { rule: 'ctx.status === "approved"', context: { status: 'approved' } }
      },
      {
        name: 'Complex logical expression',
        request: { rule: 'ctx.age >= 18 && ctx.country === "US"', context: { age: 21, country: 'US' } }
      },
      {
        name: 'Accessing request properties',
        request: { rule: 'req.method === "POST"', context: {} }
      },
      {
        name: 'False result',
        request: { rule: 'ctx.value < 0', context: { value: 10 } }
      }
    ];

    for (const test of tests) {
      console.log(`\n=== Test: ${test.name} ===`);

      const response = await fetch('http://localhost:3001/check', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(test.request)
      });

      const data = await response.json();
      console.log('Status:', response.status);
      console.log('Response:', JSON.stringify(data, null, 2));
      console.log('Rule:', test.request.rule);
      console.log('Context:', test.request.context);
    }

    // Test error cases
    console.log('\n=== Test: Invalid expression ===');
    const errorResponse = await fetch('http://localhost:3001/check', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        rule: 'ctx.missing.property > 0', 
        context: { amount: 100 } 
      })
    });

    const errorData = await errorResponse.json();
    console.log('Status:', errorResponse.status);
    console.log('Response:', JSON.stringify(errorData, null, 2));

  } catch (error) {
    console.error('Test error:', error);
  } finally {
    server.close();
  }
})();

