        console.log(`✓ PASS`);
      } else {
        console.log(`✗ FAIL`);
        console.log(`  Expected status: ${test.expectedStatus}`);
        console.log(`  Expected body to contain: ${test.expectedBodyContains}`);
      }
    }
  } catch (error) {
    console.error('Test error:', error);
  } finally {
    server.close();
    console.log('\nServer stopped');
  }
});

