function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST /check endpoint for evaluating rule expressions
app.post('/check', (req, res) => {
  try {
    // Check if rule expression is provided
    if (!req.body.rule) {
      return res.status(400).json({ error: 'Missing rule expression' });
    }

    // Evaluate the rule using the reference implementation
    const result = evalRule(req);

    // Return the evaluation result
    res.json({
      success: true,
      result: result,
      rule: req.body.rule,
      context: req.body.context || {}
    });
  } catch (error) {
    // Handle any evaluation errors
    res.status(400).json({
      error: 'Rule evaluation failed',
      message: error.message,
      rule: req.body.rule
    });
  }
});

