// Test script for the /check endpoint
const express = require('express');
const request = require('supertest');

// Import our app
const app = require('./app.js');

// Test the /check endpoint
async function testCheckEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Valid rule expression
  console.log('Test 1: Valid rule expression');
  const response1 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/);

  console.log('Response:', JSON.stringify(response1.body, null, 2));
  console.log('Expected result: true\n');

  // Test 2: Another valid rule expression
  console.log('Test 2: Another valid rule expression');
  const response2 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.user.age >= 18',
      context: { user: { age: 25, name: 'John' } }
    })
    .expect('Content-Type', /json/);

  console.log('Response:', JSON.stringify(response2.body, null, 2));
  console.log('Expected result: true\n');

  // Test 3: Rule using request object
  console.log('Test 3: Rule using request object');
  const response3 = await request(app)
    .post('/check')
    .set('X-Test-Header', 'test-value')
    .send({
      rule: "req.headers['x-test-header'] === 'test-value'",
      context: {}
    })
    .expect('Content-Type', /json/);

  console.log('Response:', JSON.stringify(response3.body, null, 2));
  console.log('Expected result: true\n');

  // Test 4: Missing rule field
  console.log('Test 4: Missing rule field');
  const response4 = await request(app)
    .post('/check')
    .send({
      context: { amount: 150 }
    })
    .expect(400);

  console.log('Response:', JSON.stringify(response4.body, null, 2));
  console.log('Expected error: Missing required field: rule\n');

  // Test 5: Invalid rule expression
  console.log('Test 5: Invalid rule expression');
  const response5 = await request(app)
    .post('/check')
    .send({
      rule: 'invalid javascript syntax {{',
      context: {}
    })
    .expect(400);

  console.log('Response:', JSON.stringify(response5.body, null, 2));
  console.log('Expected error: Syntax error\n');

  console.log('All tests completed!');
}

// Run the test
testCheckEndpoint().catch(console.error);

