// Test script for POST /check endpoint
const express = require('express');
const request = require('supertest');
const app = require('./app.js');

describe('POST /check endpoint', () => {
  it('should evaluate a simple rule expression', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    console.log('Test 1 - Simple rule (ctx.amount > 100 with ctx.amount = 150):');
    console.log('Response:', response.status, response.body);
    console.log('Expected result: true');
    console.log('---');
  });

  it('should evaluate rule with req object access', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'req.body.context.user === "admin"',
        context: { user: 'admin' }
      });

    console.log('Test 2 - Rule with req object access:');
    console.log('Response:', response.status, response.body);
    console.log('Expected result: true');
    console.log('---');
  });

  it('should handle complex rule expressions', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.age >= 18 && ctx.country === "US"',
        context: { age: 21, country: 'US' }
      });

    console.log('Test 3 - Complex rule (ctx.age >= 18 && ctx.country === "US"):');
    console.log('Response:', response.status, response.body);
    console.log('Expected result: true');
    console.log('---');
  });

  it('should return error for missing rule', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        // Missing rule field
        context: { amount: 150 }
      });

    console.log('Test 4 - Missing rule:');
