// Test the POST /check endpoint
const app = require('./app');
const request = require('supertest');

// Test cases based on the example from docs/RULES_ENGINE.md
const testCases = [
  {
    name: 'Simple amount comparison',
    requestBody: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expectedResult: true
  },
  {
    name: 'Simple amount comparison (false case)',
    requestBody: {
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    },
    expectedResult: false
  },
  {
    name: 'Complex rule with multiple conditions',
    requestBody: {
      rule: 'ctx.amount > 100 && ctx.user.role === "admin"',
      context: { 
        amount: 150,
        user: { role: 'admin' }
      }
    },
    expectedResult: true
  },
  {
    name: 'Rule with request object access',
    requestBody: {
      rule: 'ctx.amount > 100 && req.method === "POST"',
      context: { amount: 150 }
    },
    expectedResult: true
  }
];

// Run tests
describe('POST /check endpoint', () => {
  testCases.forEach(testCase => {
    it(`should evaluate ${testCase.name} correctly`, async () => {
      const response = await request(app)
        .post('/check')
        .send(testCase.requestBody)
        .set('Content-Type', 'application/json');

      expect(response.status).toBe(200);
      expect(response.body.result).toBe(testCase.expectedResult);
      expect(response.body.rule).toBe(testCase.requestBody.rule);
      expect(response.body.context).toEqual(testCase.requestBody.context);
    });
  });

  it('should return error for missing rule field', async () => {
    const response = await request(app)
      .post('/check')
      .send({ context: { amount: 100 } })
      .set('Content-Type', 'application/json');

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing required field: rule');
  });

  it('should return error for invalid rule expression', async () => {
    const response = await request(app)
      .post('/check')
      .send({ 
        rule: 'this is not valid javascript',
        context: { amount: 100 }
      })
      .set('Content-Type', 'application/json');

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Rule evaluation failed');
  });
});

