const fetch = (...args) => import('node-fetch').then(({default: fetch}) => fetch(...args));

async function testEndpoint() {
  const baseUrl = 'http://localhost:3000';

  console.log('Demonstrating POST /check endpoint\n');

  // Test case 1: Simple amount comparison
  console.log('Test 1: Simple amount comparison');
  const payload1 = {
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  };

  try {
    const response1 = await fetch(`${baseUrl}/check`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload1)
    });

    const result1 = await response1.json();
    console.log('Request:', JSON.stringify(payload1, null, 2));
    console.log('Response:', JSON.stringify(result1, null, 2));
    console.log(`Result: ${result1.result} (150 > 100 = ${result1.result})\n`);
  } catch (error) {
    console.error('Error:', error.message);
  }

  // Test case 2: Complex rule with user role
  console.log('Test 2: Complex rule with user role');
  const payload2 = {
    rule: 'ctx.user.age >= 18 && ctx.user.role === "admin"',
    context: { 
      user: { 
        age: 25, 
        role: 'admin',
        name: 'Alice' 
      }
    }
  };

  try {
    const response2 = await fetch(`${baseUrl}/check`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload2)
    });

    const result2 = await response2.json();
    console.log('Request:', JSON.stringify(payload2, null, 2));
    console.log('Response:', JSON.stringify(result2, null, 2));
    console.log(`Result: ${result2.result} (age >= 18 AND role = "admin" = ${result2.result})\n`);
  } catch (error) {
    console.error('Error:', error.message);
  }

  // Test case 3: Rule with arithmetic
  console.log('Test 3: Rule with arithmetic calculation');
  const payload3 = {
    rule: '(ctx.price * ctx.quantity) > 1000',
    context: { 
      price: 50,
      quantity: 25
    }
  };

  try {
    const response3 = await fetch(`${baseUrl}/check`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload3)
    });

    const result3 = await response3.json();
    console.log('Request:', JSON.stringify(payload3, null, 2));
    console.log('Response:', JSON.stringify(result3, null, 2));
    console.log(`Result: ${result3.result} (50 * 25 > 1000 = ${result3.result ? 'true' : 'false'})\n`);
  } catch (error) {
    console.error('Error:', error.message);
  }

  console.log('To run this demo:');
  console.log('1. Start the server: npm start');
  console.log('2. In another terminal, run: node demo.js');
}

testEndpoint();

