#!/usr/bin/env node

// Test script for the /check endpoint

const http = require('http');

const testData = {
  validRule: {
    rule: 'ctx.amount > 100 && ctx.user === "admin"',
    context: {
      amount: 150,
      user: 'admin'
    }
  },
  invalidRule: {
    rule: 'invalid syntax &&',  // Invalid JavaScript syntax
    context: {
      amount: 150
    }
  },
  missingRule: {
    context: {
      amount: 150
    }
  },
  missingContext: {
    rule: 'ctx.amount > 100'
  }
};

function makeRequest(data, description) {
  const postData = JSON.stringify(data);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      try {
        const parsed = JSON.parse(responseData);
        console.log(`\n${description}:`);
        console.log(`Status: ${res.statusCode}`);
        console.log(`Response:`, parsed);
      } catch (e) {
        console.log(`\n${description}:`);
        console.log(`Status: ${res.statusCode}`);
        console.log(`Raw response:`, responseData);
      }
    });
  });

  req.on('error', (e) => {
    console.error(`\n${description}: Error - ${e.message}`);
  });

  req.write(postData);
  req.end();
}

// Check if server is running first
const checkOptions = {
  hostname: 'localhost',
  port: 3000,
  path: '/health',
  method: 'GET'
};

console.log('Testing /check endpoint...\n');

// Make test requests
setTimeout(() => {
  console.log('Test 1: Valid rule evaluation');
  makeRequest(testData.validRule, 'Valid rule');

  setTimeout(() => {
    console.log('\nTest 2: Invalid rule syntax');
    makeRequest(testData.invalidRule, 'Invalid syntax');

    setTimeout(() => {
      console.log('\nTest 3: Missing rule field');
      makeRequest(testData.missingRule, 'Missing rule');

      setTimeout(() => {
        console.log('\nTest 4: Missing context field');
        makeRequest(testData.missingContext, 'Missing context');
      }, 1000);
    }, 1000);
  }, 1000);
}, 1000);

