const request = require('supertest');
const app = require('./app');

// Simple test cases
const testCases = [
  {
    name: 'Simple numeric comparison',
    requestBody: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expectedResult: true
  },
  {
    name: 'String comparison',
    requestBody: {
      rule: 'ctx.user.role === "admin"',
      context: { user: { role: 'admin', name: 'Alice' } }
    },
    expectedResult: true
  },
  {
    name: 'Complex logical expression',
    requestBody: {
      rule: 'ctx.age >= 18 && ctx.country === "US"',
      context: { age: 25, country: 'US' }
    },
    expectedResult: true
  },
  {
    name: 'Using req object',
    requestBody: {
      rule: 'req.method === "POST" && ctx.value',
      context: { value: true }
    },
    expectedResult: true
  },
  {
    name: 'False condition',
    requestBody: {
      rule: 'ctx.score > 90',
      context: { score: 85 }
    },
    expectedResult: false
  }
];

async function runTests() {
  console.log('Testing POST /check endpoint...\n');

  for (const testCase of testCases) {
    console.log(`Test: ${testCase.name}`);
    console.log(`Rule: ${testCase.requestBody.rule}`);
    console.log(`Context: ${JSON.stringify(testCase.requestBody.context)}`);

    const response = await request(app)
      .post('/check')
      .send(testCase.requestBody)
      .set('Accept', 'application/json');

    console.log(`Status: ${response.status}`);
    console.log(`Response: ${JSON.stringify(response.body, null, 2)}`);

    if (response.status === 200 && response.body.result === testCase.expectedResult) {
