// Test script for the POST /check endpoint
const app = require('./app');
const request = require('supertest');

// Test cases
const testCases = [
  {
    name: 'Simple comparison without context',
    body: { rule: '5 > 3' },
    expectedResult: true
  },
  {
    name: 'Simple comparison with context',
    body: { rule: 'ctx.amount > 100', context: { amount: 150 } },
    expectedResult: true
  },
  {
    name: 'Complex rule with logical operators',
    body: { 
      rule: 'ctx.age >= 18 && ctx.country === "US"', 
      context: { age: 25, country: 'US' } 
    },
    expectedResult: true
  },
  {
    name: 'Access to request properties',
    body: { 
      rule: 'req.method === "POST"', 
      context: {} 
    },
    expectedResult: true
  },
  {
    name: 'False condition',
    body: { 
      rule: 'ctx.score > 90', 
      context: { score: 85 } 
    },
    expectedResult: false
  }
];

// Run tests
async function runTests() {
  console.log('Testing POST /check endpoint...\n');

  for (const testCase of testCases) {
    const response = await request(app)
      .post('/check')
      .send(testCase.body)
      .set('Content-Type', 'application/json');

    console.log(`Test: ${testCase.name}`);
    console.log(`Request: ${JSON.stringify(testCase.body)}`);
    console.log(`Response status: ${response.status}`);
    console.log(`Response body: ${JSON.stringify(response.body)}`);

    if (response.status === 200 && response.body.result === testCase.expectedResult) {
      console.log('✓ PASS\n');
    } else {
      console.log('✗ FAIL\n');
    }
  }

  // Test error cases
  console.log('Testing error cases...\n');

  // Missing rule
  const missingRuleResponse = await request(app)
    .post('/check')
    .send({ context: { amount: 100 } })
    .set('Content-Type', 'application/json');

  console.log('Missing rule test:');
  console.log(`Status: ${missingRuleResponse.status} (expected 400)`);
  console.log(`Body: ${JSON.stringify(missingRuleResponse.body)}`);
  console.log(missingRuleResponse.status === 400 ? '✓ PASS\n' : '✗ FAIL\n');

  // Invalid rule syntax
  const invalidSyntaxResponse = await request(app)
    .post('/check')
    .send({ rule: 'ctx.amount > ' })
    .set('Content-Type', 'application/json');

  console.log('Invalid syntax test:');
  console.log(`Status: ${invalidSyntaxResponse.status} (expected 400)`);
  console.log(`Body: ${JSON.stringify(invalidSyntaxResponse.body)}`);
  console.log(invalidSyntaxResponse.status === 400 ? '✓ PASS\n' : '✗ FAIL\n');
}

// Note: This test requires supertest to be installed
console.log('Note: This test requires supertest to be installed.');
console.log('Run: npm install supertest --save-dev');
console.log('Then run: node test_check_endpoint.js');

// Simple test to demonstrate the evalRule function
